-- Wave A8: Convert 0/1 integer flags to boolean. Rollback: TYPE integer USING CASE WHEN col THEN 1 ELSE 0 END.
DO $$ BEGIN IF to_regclass('addresses') IS NOT NULL AND EXISTS (SELECT 1 FROM information_schema.columns WHERE table_name='addresses' AND column_name='is_default' AND data_type <> 'boolean') THEN ALTER TABLE addresses ALTER COLUMN is_default DROP DEFAULT; ALTER TABLE addresses ALTER COLUMN is_default TYPE boolean USING CASE WHEN is_default::text IN ('1','t','true','yes','y') THEN true ELSE false END; ALTER TABLE addresses ALTER COLUMN is_default SET DEFAULT false; END IF; END $$;
